// Generates src/theme/tokens.ts from packages/design/tokens.json (single design source for web and native).
import { readFileSync, writeFileSync } from 'node:fs';

const tokens = JSON.parse(readFileSync(new URL('../../design/tokens.json', import.meta.url), 'utf8'));
const output = new URL('../src/theme/tokens.ts', import.meta.url);
const body =
  '/** Generated by packages/ui/scripts/tokens.mjs from packages/design/tokens.json. Do not edit. */\n' +
  Object.entries(tokens)
    .map(([group, values]) => `export const ${group} = ${JSON.stringify(values, null, 2)} as const;\n`)
    .join('\n');
if (process.argv.includes('--check')) {
  if (readFileSync(output, 'utf8') !== body) {
    console.error('stale tokens: run npm run tokens -w @morydeals/ui');
    process.exit(1);
  }
} else {
  writeFileSync(output, body);
}
